def bbox_mask(g, vals):
    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v in vals]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    return [[g[r][c] if g[r][c] in vals else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)], (r0,c0,r1,c1)
