# Use each piece's actual digit; 5 belongs to piece 7.
def assemble_candidates(N, allow_reflect=False):
    sols=[]
    for order in itertools.permutations([2,3,8],3): # TR, BL, BR
      assigned=(7,)+order
      for ks in itertools.product(range(4), repeat=3):
        rots={7:rotk(pieces[7],2)}
        for v,k in zip(order,ks): rots[v]=rotk(pieces[v],k)
        # marked piece should put marker at its top-left
        m7=rots[7]
        p5=[(r,c) for r,row in enumerate(m7) for c,x in enumerate(row) if x==5]
        if p5 != [(0,0)]: continue
        placements=[]
        for pos,v in zip(('tl','tr','bl','br'),assigned):
          a=rots[v]; h=len(a); w=len(a[0])
          if h>N or w>N: break
          r0=0 if pos[0]=='t' else N-h
          c0=0 if pos[1]=='l' else N-w
          placements.append((pos,v,a,r0,c0))
        else:
          canvas=[[0]*N for _ in range(N)]; count=[[0]*N for _ in range(N)]
          okay=True
          for pos,v,a,r0,c0 in placements:
            for r,row in enumerate(a):
              for c,x in enumerate(row):
                if x:
                  if count[r0+r][c0+c]: okay=False
                  count[r0+r][c0+c]+=1
                  canvas[r0+r][c0+c]=x
          if okay and all(x==1 for row in count for x in row):
            sols.append((assigned, {v:k for v,k in zip(order,ks)}, canvas, placements))
    return sols
